<script setup lang="ts">import type { BirthDateInput } from '../api/contracts'; const props=defineProps<{ modelValue: BirthDateInput; disabled?: boolean }>(); const emit=defineEmits<{ 'update:modelValue': [value: BirthDateInput] }>(); function update(part: keyof BirthDateInput,event: Event) { emit('update:modelValue',{...props.modelValue,[part]:(event.target as HTMLInputElement).value}); }</script>
<template><fieldset id="REG-005" class="wareki" :disabled="disabled"><legend>生年月日 ※必須</legend><select aria-label="元号" :value="modelValue.era" @change="update('era',$event)"><option value="">元号</option><option value="REIWA">令和</option><option value="HEISEI">平成</option><option value="SHOWA">昭和</option><option value="TAISHO">大正</option><option value="MEIJI">明治</option></select><input aria-label="元号年" maxlength="4" :value="modelValue.year" placeholder="元／年" @input="update('year',$event)"><span>年</span><input aria-label="月" maxlength="2" :value="modelValue.month" @input="update('month',$event)"><span>月</span><input aria-label="日" maxlength="2" :value="modelValue.day" @input="update('day',$event)"><span>日</span></fieldset></template>
